SELECT d.id, ROUND(100.0 * SUM(CASE WHEN a.status='NO_SHOW' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN a.status IN ('COMPLETED','NO_SHOW') THEN 1 ELSE 0 END),0),1) AS no_show_pct FROM doctors d LEFT JOIN slots s ON s.doctor_id=d.id AND s.starts_at >= '2026-09-30T16:00:00Z' AND s.starts_at < '2026-10-31T16:00:00Z' LEFT JOIN appointments a ON a.slot_id=s.id GROUP BY d.id ORDER BY d.id;
